import pandas as pd
from collections import Counter, defaultdict
from typing import List, Tuple

from solver import Algorithm


class Evolved(Algorithm):
    """Validity-preserving row-wise column permutation optimizer."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional source frame and initialize shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _text(value) -> str:
        """Convert one cell to the evaluator's missing-as-empty serialization."""
        try:
            missing = pd.isna(value)
            if bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(a: str, b: str) -> int:
        """Return the exact character longest-common-prefix length."""
        limit = min(len(a), len(b))
        if limit == 0 or a[0] != b[0]:
            return 0
        lo, hi = 1, limit
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if a[:mid] == b[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _reuse(cls, strings: List[str]) -> int:
        """Compute exact ideal Trie reuse from lexicographically adjacent rows."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        return sum(cls._lcp(a, b) for a, b in zip(ordered, ordered[1:]))

    @staticmethod
    def _merge(columns, order, col_merge):
        """Make requested source-column groups contiguous without dropping columns."""
        if not col_merge:
            return list(order)

        position = {c: i for i, c in enumerate(order)}
        groups = {}
        claimed = set()

        for request in col_merge:
            group = [c for c in order if c in request and c not in claimed]
            if not group:
                continue
            group.sort(key=position.__getitem__)
            for c in group:
                groups[c] = group
                claimed.add(c)

        answer = []
        emitted = set()
        for c in order:
            if c in emitted:
                continue
            group = groups.get(c)
            if group is None:
                answer.append(c)
                emitted.add(c)
            else:
                answer.extend(group)
                emitted.update(group)
        return answer

    @staticmethod
    def _strings(text, orders):
        """Serialize every row according to its row-specific source-column order."""
        return ["".join(text[r][j] for j in orders[r]) for r in range(len(orders))]

    def _global_orders(self, text, columns, col_merge):
        """Build two deterministic global orders using repetition-weighted statistics."""
        n = len(text)
        m = len(columns)
        stats = []

        for j in range(m):
            counts = Counter(text[r][j] for r in range(n))
            pair_mass = sum(len(v) * c * (c - 1)
                            for v, c in counts.items())
            repeat_mass = sum(len(v) * (c - 1)
                              for v, c in counts.items())
            stats.append((pair_mass, repeat_mass, len(counts)))

        pair_rank = sorted(
            range(m),
            key=lambda j: (-stats[j][0], -stats[j][1], stats[j][2], j),
        )
        repeat_rank = sorted(
            range(m),
            key=lambda j: (-stats[j][1], -stats[j][0], stats[j][2], j),
        )

        lookup = {c: j for j, c in enumerate(columns)}
        answers = []
        for ranking in (pair_rank, repeat_rank):
            names = self._merge(
                columns, [columns[j] for j in ranking], col_merge
            )
            answers.append([lookup[c] for c in names])
        return answers, pair_rank, stats

    def _conditional(self, text, columns, col_merge, global_order, stats):
        """Construct bounded conditional prefix orders using repeated field values."""
        n = len(text)
        m = len(columns)
        result = [None] * n
        candidates = [
            j for j in global_order if stats[j][0] > 0
        ][:min(20, m)]
        candidate_set = set(candidates)
        node_limit = 384
        max_depth = min(8, len(candidates))
        nodes = 0
        lookup = {c: j for j, c in enumerate(columns)}

        def complete(rows, prefix, remaining):
            """Assign a complete valid order to all rows in one terminal group."""
            tail = [j for j in global_order if j in remaining]
            names = self._merge(
                columns, [columns[j] for j in prefix + tail], col_merge
            )
            order = [lookup[c] for c in names]
            for r in rows:
                result[r] = order[:]

        def visit(rows, remaining, prefix, depth):
            """Split one group once on its best length-weighted repeated field."""
            nonlocal nodes
            nodes += 1
            branchable = [j for j in remaining if j in candidate_set]
            if (
                len(rows) < 2
                or not branchable
                or depth >= max_depth
                or nodes > node_limit
            ):
                complete(rows, prefix, remaining)
                return

            best_j = -1
            best_score = 0
            best_groups = None

            for j in branchable:
                groups = defaultdict(list)
                for r in rows:
                    groups[text[r][j]].append(r)
                score = sum(
                    len(value) * len(members) * (len(members) - 1)
                    for value, members in groups.items()
                    if len(members) > 1
                )
                if score > best_score or (
                    score == best_score and score > 0
                    and (best_j < 0 or j < best_j)
                ):
                    best_j = j
                    best_score = score
                    best_groups = groups

            if best_j < 0 or best_score == 0:
                complete(rows, prefix, remaining)
                return

            rest = [j for j in remaining if j != best_j]
            parts = sorted(
                best_groups.values(),
                key=lambda group: (-len(group), min(group)),
            )
            for group in parts:
                visit(group, rest, prefix + [best_j], depth + 1)

        visit(list(range(n)), list(range(m)), [], 0)
        fallback = list(global_order)
        for r in range(n):
            if result[r] is None:
                result[r] = fallback[:]
        return result

    def _refine(self, text, columns, col_merge, seed):
        """Run two bounded frontier coordinate passes over a seed permutation.

        Each selected row is compared with its lexicographic predecessor and
        successor.  At most twelve columns are tested using front insertion
        and a boundary-crossing insertion.  A move is retained only when its
        direct LCP with one frontier target strictly improves.
        """
        n, m = len(text), len(columns)
        if n > 192 or m > 24:
            return seed

        orders = [list(order) for order in seed]
        lookup = {c: j for j, c in enumerate(columns)}

        for _ in range(2):
            serial = self._strings(text, orders)
            frontier = sorted(range(n), key=lambda r: serial[r])
            changed = False

            for p, row in enumerate(frontier):
                targets = []
                if p:
                    targets.append(serial[frontier[p - 1]])
                if p + 1 < n:
                    targets.append(serial[frontier[p + 1]])
                if not targets:
                    continue

                old_order = orders[row]
                best_order = old_order
                best_gain = 0
                inspect = old_order[:min(12, m)]

                for col in inspect:
                    if col not in old_order:
                        continue
                    pos = old_order.index(col)

                    proposals = []
                    if pos != 0:
                        proposals.append([col] + old_order[:pos] + old_order[pos + 1:])

                    # Move the field across the first current field boundary
                    # whose value disagrees with at least one frontier target.
                    boundary = 0
                    for k, field in enumerate(old_order):
                        value = text[row][field]
                        if any(target.startswith(value) is False
                               for target in targets) and k > 0:
                            boundary = k
                            break
                    if pos != boundary:
                        remainder = old_order[:pos] + old_order[pos + 1:]
                        proposals.append(
                            remainder[:boundary] + [col] + remainder[boundary:]
                        )

                    for proposal in proposals:
                        names = self._merge(
                            columns,
                            [columns[j] for j in proposal],
                            col_merge,
                        )
                        candidate = [lookup[c] for c in names]
                        candidate_text = "".join(text[row][j] for j in candidate)
                        gain = max(
                            self._lcp(candidate_text, target)
                            - self._lcp(serial[row], target)
                            for target in targets
                        )
                        if gain > best_gain:
                            best_gain = gain
                            best_order = candidate

                if best_gain > 0:
                    orders[row] = best_order
                    changed = True

            if not changed:
                break

        return orders

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Select the best bounded candidate and return its reordered frame."""
        self.df = df
        self.num_rows, self.num_cols = df.shape
        n, m = df.shape
        columns = list(df.columns)

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        text = [
            [self._text(raw[r, j]) for j in range(m)]
            for r in range(n)
        ]

        global_orders, base_order, stats = self._global_orders(
            text, columns, col_merge
        )

        candidates = []
        for order in global_orders:
            orders = [order[:] for _ in range(n)]
            serial = self._strings(text, orders)
            candidates.append((self._reuse(serial), orders, serial))

        conditional = self._conditional(
            text, columns, col_merge, base_order, stats
        )
        conditional_serial = self._strings(text, conditional)
        candidates.append((
            self._reuse(conditional_serial),
            conditional,
            conditional_serial,
        ))

        # Refine the strongest seed, then compare it against every incumbent.
        seed_score, seed_orders, _ = max(
            candidates, key=lambda item: item[0]
        )
        refined = self._refine(text, columns, col_merge, seed_orders)
        refined_serial = self._strings(text, refined)
        candidates.append((
            self._reuse(refined_serial),
            refined,
            refined_serial,
        ))

        _, best_orders, best_serial = max(
            candidates, key=lambda item: item[0]
        )
        row_order = sorted(range(n), key=lambda r: best_serial[r])

        output = [
            [raw[r, j] for j in best_orders[r]]
            for r in row_order
        ]
        orderings = [
            [columns[j] for j in best_orders[r]]
            for r in row_order
        ]

        result = pd.DataFrame(
            output,
            columns=columns,
            index=df.index.take(row_order),
            dtype=object,
        )
        return result, orderings

